import { civiewGetList, showtypeList, civiewsave } from "@/api/system/ciModel";
import draggable from 'vuedraggable';

export default {
  props: ["isShow", "ciId", "isVirtual"],
  data() {
    return{
      dragOptions: {
        animation: 150,
        scroll: true,
        group: 'description',
        disabled: false,
        ghostClass: 'ghost'
      },
      attrRelList: [],
      viewList: [],
      saveLoading: false
    }
  },
  mounted() {
    this.getDict()
    this.getList()
  },
  methods: {
    getList() {
      civiewGetList({ciId: this.ciId}).then(res => {
        this.attrRelList = res.Return
      })
    },
    getDict() {
      showtypeList().then(res => {
        this.viewList = res.Return
      })
    },
    save() {
      this.saveLoading = true
      civiewsave({
        ciId: this.ciId,
        ciViewList: this.attrRelList
      }).then(res => {
        this.$emit('saveView')
        this.saveLoading = false
      }).catch(() => {
        this.saveLoading = false
      })
    }
  }
}
